-- AK Tarifas: catálogo interno para atención al cliente y administración.
create table if not exists public.tarifas_servicios (
  id uuid primary key default gen_random_uuid(),
  codigo text not null unique,
  categoria text not null check (categoria in ('llaves', 'ecus', 'reparaciones', 'talleres', 'files')),
  familia text,
  marca text,
  modelo text,
  anios text,
  motor text,
  sistema text,
  ecu text,
  combustible text,
  acceso text,
  transponder text,
  espadin text,
  situacion text,
  servicio text not null,
  descripcion text,
  pvp numeric(10,2) not null check (pvp >= 0),
  precio_minimo numeric(10,2) check (precio_minimo is null or precio_minimo >= 0),
  precio_taller numeric(10,2) check (precio_taller is null or precio_taller >= 0),
  incluye text,
  condiciones text,
  plazo text,
  requiere_laboratorio boolean not null default false,
  activo boolean not null default true,
  orden integer not null default 0,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create index if not exists tarifas_servicios_categoria_idx on public.tarifas_servicios (categoria, activo, orden);
create index if not exists tarifas_servicios_marca_modelo_idx on public.tarifas_servicios (marca, modelo);

create table if not exists public.tarifas_historial (
  id uuid primary key default gen_random_uuid(),
  tarifa_id uuid not null references public.tarifas_servicios(id),
  usuario_id uuid references public.usuarios_app(id),
  usuario text,
  accion text not null check (accion in ('crear', 'editar', 'desactivar', 'activar')),
  datos_anteriores jsonb,
  datos_nuevos jsonb,
  created_at timestamptz not null default now()
);

create index if not exists tarifas_historial_tarifa_idx on public.tarifas_historial (tarifa_id, created_at desc);
create index if not exists tarifas_historial_usuario_idx on public.tarifas_historial (usuario_id);

create or replace function public.tarifas_touch_updated_at()
returns trigger
language plpgsql
set search_path = public
as $$
begin
  new.updated_at = now();
  return new;
end;
$$;

drop trigger if exists tarifas_servicios_touch_updated_at on public.tarifas_servicios;
create trigger tarifas_servicios_touch_updated_at
before update on public.tarifas_servicios
for each row execute function public.tarifas_touch_updated_at();

alter table public.tarifas_servicios enable row level security;
alter table public.tarifas_historial enable row level security;

drop policy if exists "staff puede consultar tarifas" on public.tarifas_servicios;
create policy "staff puede consultar tarifas"
on public.tarifas_servicios for select to authenticated
using (exists (
  select 1 from public.usuarios_app u
  where u.auth_user_id = auth.uid() and u.activo = true
    and u.rol in ('admin', 'desarrollo', 'laboratorio', 'administracion', 'atencion_cliente')
));

drop policy if exists "administradores gestionan tarifas" on public.tarifas_servicios;
drop policy if exists "administradores crean tarifas" on public.tarifas_servicios;
create policy "administradores crean tarifas"
on public.tarifas_servicios for insert to authenticated
with check (exists (
  select 1 from public.usuarios_app u
  where u.auth_user_id = auth.uid() and u.activo = true and u.rol = 'admin'
));

drop policy if exists "administradores editan tarifas" on public.tarifas_servicios;
create policy "administradores editan tarifas"
on public.tarifas_servicios for update to authenticated
using (exists (
  select 1 from public.usuarios_app u
  where u.auth_user_id = auth.uid() and u.activo = true and u.rol = 'admin'
))
with check (exists (
  select 1 from public.usuarios_app u
  where u.auth_user_id = auth.uid() and u.activo = true and u.rol = 'admin'
));

drop policy if exists "staff puede consultar historial de tarifas" on public.tarifas_historial;
create policy "staff puede consultar historial de tarifas"
on public.tarifas_historial for select to authenticated
using (exists (
  select 1 from public.usuarios_app u
  where u.auth_user_id = auth.uid() and u.activo = true
    and u.rol in ('admin', 'desarrollo', 'laboratorio', 'administracion', 'atencion_cliente')
));

drop policy if exists "administradores registran historial de tarifas" on public.tarifas_historial;
create policy "administradores registran historial de tarifas"
on public.tarifas_historial for insert to authenticated
with check (exists (
  select 1 from public.usuarios_app u
  where u.auth_user_id = auth.uid() and u.activo = true and u.rol = 'admin'
));

grant select on public.tarifas_servicios to authenticated;
grant select on public.tarifas_historial to authenticated;
grant insert, update on public.tarifas_servicios to authenticated;
grant insert on public.tarifas_historial to authenticated;


on conflict (codigo) do update set
  categoria = excluded.categoria,
  familia = excluded.familia,
  marca = excluded.marca,
  modelo = excluded.modelo,
  anios = excluded.anios,
  motor = excluded.motor,
  sistema = excluded.sistema,
  ecu = excluded.ecu,
  combustible = excluded.combustible,
  acceso = excluded.acceso,
  transponder = excluded.transponder,
  espadin = excluded.espadin,
  situacion = excluded.situacion,
  servicio = excluded.servicio,
  descripcion = excluded.descripcion,
  pvp = excluded.pvp,
  precio_minimo = excluded.precio_minimo,
  precio_taller = excluded.precio_taller,
  incluye = excluded.incluye,
  condiciones = excluded.condiciones,
  plazo = excluded.plazo,
  requiere_laboratorio = excluded.requiere_laboratorio,
  orden = excluded.orden;
